insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9297, 26, 'Beschäftigungspflicht durchsetzen: Ausgleichsabgabe erhöhen oder staffeln, Schlupflöcher schließen (Bund)', 'Eine spürbare Abgabe erhöht die Beschäftigung an der Quotenschwelle (Österreich, IAB); Übersichtsstudien finden aber gemischte Effekte, Betriebe weichen teils unter Schwellen aus. Der Bund regelt das im SGB IX selbst.', 'gemischt', 'https://econpapers.repec.org/RePEc:jku:nrnwps:2009_11', 'bund', null, true, 'blind'),
  (9298, 26, 'Barrieren in Bahn, Bus und an Haltestellen durch mehr Investitionen schneller abbauen (Bund)', 'Investitionen beseitigen Barrieren, wo sie verbaut werden; laut Bundesrechnungshof lag die Verzögerung aber vor allem an der Steuerung, Fördergeld blieb ungenutzt. Ohne bessere Steuerung wenig Beschleunigung; der ÖPNV liegt zudem bei Ländern.', 'gemischt', 'https://bundesrechnungshof.de/berichte/bmdv-verschleppt-investitionen-in-bahnhoefe', 'bund', null, true, 'blind'),
  (9299, 26, 'Werkstätten für behinderte Menschen zu Inklusionsbetrieben mit Mindestlohn umbauen (Bund)', 'Nach Schließung der Werkstätten fanden in Vermont viele reguläre Arbeit, in Maine sanken Stunden und Einkommen. Mindestlohn für rund 300.000 Beschäftigte und tragfähige Inklusionsbetriebe sind finanziell ungeklärt.', 'gemischt', 'https://www.publicsource.org/vermont-closed-workshops-for-people-with-disabilities-what-happened-next/', 'bund', null, true, 'blind'),
  (9300, 26, 'Vermittlung und Förderung für Arbeit auf dem allgemeinen Arbeitsmarkt stärken (Bund)', 'Vermittlung kann Menschen mit Behinderung und Betriebe mit geeigneten Tätigkeiten zusammenbringen; Förderungen wie Lohnzuschüsse wirken laut Übersichtsstudie aber uneinheitlich, die Zusage bleibt unbestimmt. Bund und Arbeitsagentur sind zuständig.', 'gemischt', 'https://pureportal.strath.ac.uk/en/publications/employer-focused-interventions-targeting-disability-employment-a-/', 'bund', null, true, 'blind'),
  (9301, 26, 'Finanzielle Anreize für Arbeitgeber, barrierefreie und zusätzliche Arbeitsplätze zu schaffen (Bund)', 'Setzt an Ausstattungskosten an, die ein Viertel der Betriebe als Hürde nennt; Betriebe wünschen vor allem Zuschüsse. Studien zu Einstellungsanreizen sind gemischt (Mitnahmeeffekte); Steuergutschriften brauchen den Bundesrat und Gegenfinanzierung.', 'gemischt', 'https://pureportal.strath.ac.uk/en/publications/employer-focused-interventions-targeting-disability-employment-a-/', 'bund', null, true, 'blind')
