  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9302, 26, 11, null, 'Barrieren in Bus und Bahn sollen schneller beseitigt werden.', '{2601}', 9298, 1, 2, null, 'Investitionen beseitigen Barrieren, wo sie verbaut werden; laut Bundesrechnungshof lag die Verzögerung aber vor allem an der Steuerung, Fördergeld blieb ungenutzt. Ohne bessere Steuerung wenig Beschleunigung; der ÖPNV liegt zudem bei Ländern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=62', 'https://bundesrechnungshof.de/berichte/bmdv-verschleppt-investitionen-in-bahnhoefe', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9303, 26, 11, null, 'Zugang zu Ausbildung und Arbeit erleichtern: Vermittlung auf den ersten Arbeitsmarkt sowie Inklusionsbetriebe und Werkstätten stärken.', '{2602}', 9300, 2, 3, null, 'Vermittlung kann Menschen mit Behinderung und Betriebe mit geeigneten Tätigkeiten zusammenbringen; Förderungen wie Lohnzuschüsse wirken laut Übersichtsstudie aber uneinheitlich, die Zusage bleibt unbestimmt. Bund und Arbeitsagentur sind zuständig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=61', 'https://pureportal.strath.ac.uk/en/publications/employer-focused-interventions-targeting-disability-employment-a-/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9304, 26, 12, null, 'Barrierefreiheit auch in der Mobilität zu einem Schwerpunkt machen', '{2601}', 9298, 1, 2, null, 'Investitionen beseitigen Barrieren, wo sie verbaut werden; laut Bundesrechnungshof lag die Verzögerung aber vor allem an der Steuerung, Fördergeld blieb ungenutzt. Ohne bessere Steuerung wenig Beschleunigung; der ÖPNV liegt zudem bei Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=39', 'https://bundesrechnungshof.de/berichte/bmdv-verschleppt-investitionen-in-bahnhoefe', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9305, 26, 12, null, 'Aufnahme einer Arbeit auf dem allgemeinen Arbeitsmarkt verstärkt fördern und Werkstätten weiterentwickeln', '{2602}', 9300, 2, 3, null, 'Vermittlung kann Menschen mit Behinderung und Betriebe mit geeigneten Tätigkeiten zusammenbringen; Förderungen wie Lohnzuschüsse wirken laut Übersichtsstudie aber uneinheitlich, die Zusage bleibt unbestimmt. Bund und Arbeitsagentur sind zuständig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=39', 'https://pureportal.strath.ac.uk/en/publications/employer-focused-interventions-targeting-disability-employment-a-/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9306, 26, 13, null, 'Erhebliche Investitionen in umfassende Barrierefreiheit im Verkehr, an Haltestellen und Mobilitätsangeboten.', '{2601}', 9298, 1, 2, null, 'Investitionen beseitigen Barrieren, wo sie verbaut werden; laut Bundesrechnungshof lag die Verzögerung aber vor allem an der Steuerung, Fördergeld blieb ungenutzt. Ohne bessere Steuerung wenig Beschleunigung; der ÖPNV liegt zudem bei Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', 'https://bundesrechnungshof.de/berichte/bmdv-verschleppt-investitionen-in-bahnhoefe', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9307, 26, 13, null, 'Veraltete Regelwerke erneuern, um Ausnahmen bei der Barrierefreiheit im Nahverkehr zu beenden.', '{2601}', null, 2, 2, null, 'Das Ende von Ausnahmen schafft verbindlichen Druck, Haltestellen und Fahrzeuge barrierefrei zu machen; die Wirkung ist kaum untersucht. Umsetzung liegt bei Ländern und Kommunen, die Finanzierung ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=48', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9308, 26, 13, null, 'Gesetzliche Schlupflöcher bei der Beschäftigungspflicht schließen und die Ausgleichsabgabe anpassen.', '{2602}', 9297, 2, 3, null, 'Eine spürbare Abgabe erhöht die Beschäftigung an der Quotenschwelle (Österreich, IAB); Übersichtsstudien finden aber gemischte Effekte, Betriebe weichen teils unter Schwellen aus. Der Bund regelt das im SGB IX selbst.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=123', 'https://econpapers.repec.org/RePEc:jku:nrnwps:2009_11', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9309, 26, 13, null, 'Werkstättensystem schrittweise zu Inklusionsunternehmen weiterentwickeln, mit Mindestlohn und individueller Unterstützung.', '{2602}', 9299, 2, 1, null, 'Nach Schließung der Werkstätten fanden in Vermont viele reguläre Arbeit, in Maine sanken Stunden und Einkommen. Mindestlohn für rund 300.000 Beschäftigte und tragfähige Inklusionsbetriebe sind finanziell ungeklärt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=123', 'https://www.publicsource.org/vermont-closed-workshops-for-people-with-disabilities-what-happened-next/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9310, 26, 14, null, 'Praxisnahe Förderung und Arbeitsvermittlung für Menschen mit Behinderung, um Chancen auf dem ersten Arbeitsmarkt zu verbessern.', '{2602}', 9300, 2, 3, null, 'Vermittlung kann Menschen mit Behinderung und Betriebe mit geeigneten Tätigkeiten zusammenbringen; Förderungen wie Lohnzuschüsse wirken laut Übersichtsstudie aber uneinheitlich, die Zusage bleibt unbestimmt. Bund und Arbeitsagentur sind zuständig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=25', 'https://pureportal.strath.ac.uk/en/publications/employer-focused-interventions-targeting-disability-employment-a-/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9311, 26, 16, null, 'Bahnnetz sanieren, elektrifizieren und Strecken ausbauen bzw. reaktivieren, dabei barrierefrei', '{2601}', 9298, 1, 2, null, 'Investitionen beseitigen Barrieren, wo sie verbaut werden; laut Bundesrechnungshof lag die Verzögerung aber vor allem an der Steuerung, Fördergeld blieb ungenutzt. Ohne bessere Steuerung wenig Beschleunigung; der ÖPNV liegt zudem bei Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', 'https://bundesrechnungshof.de/berichte/bmdv-verschleppt-investitionen-in-bahnhoefe', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9312, 26, 16, null, 'Beschäftigungspflicht für Menschen mit Behinderung wieder auf sechs Prozent anheben, ohne Freikaufen', '{2602}', null, 1, 1, null, 'Die Senkung der Quote von 6 auf 5 % (2000) veränderte die Beschäftigungschancen laut IAB-Studie nicht; Abgaben wirken eher an Schwellen. Eine Pflicht ohne Abgabe als Ausgleich wirft Fragen der Berufsfreiheit auf, wenn geeignete Bewerbungen fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=54', 'https://iab.de/publication/?id=591316', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9313, 26, 16, null, 'Inklusionsbetriebe besser öffentlich finanzieren', '{2602}', null, 2, 3, null, 'Inklusionsbetriebe schaffen Arbeitsplätze mit passenden Tätigkeiten; die BMAS-Evaluation bewertet die Beschäftigung dort als nachhaltig. Die Zahl der Plätze ist begrenzt, ohne Betrag bleibt der Umfang der Förderung offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=54', 'https://www.bmas.de/DE/Service/Publikationen/Forschungsberichte/fb-578-foerderung-inklusionsbetriebe.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (9314, 26, 17, null, 'Mehr Anreize für Betriebe, barrierefreie Arbeitsplätze zu schaffen.', '{2602}', 9301, 2, 2, null, 'Setzt an Ausstattungskosten an, die ein Viertel der Betriebe als Hürde nennt; Betriebe wünschen vor allem Zuschüsse. Studien zu Einstellungsanreizen sind gemischt (Mitnahmeeffekte); Steuergutschriften brauchen den Bundesrat und Gegenfinanzierung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=22', 'https://pureportal.strath.ac.uk/en/publications/employer-focused-interventions-targeting-disability-employment-a-/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9315, 26, 18, null, 'Ausgleichsabgabe für Betriebe, die zu wenige Menschen mit Behinderung beschäftigen, wird nach Unternehmensgröße und Erfüllungsgrad der Quote gestaffelt.', '{2602}', 9297, 2, 3, null, 'Eine spürbare Abgabe erhöht die Beschäftigung an der Quotenschwelle (Österreich, IAB); Übersichtsstudien finden aber gemischte Effekte, Betriebe weichen teils unter Schwellen aus. Der Bund regelt das im SGB IX selbst.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=146', 'https://econpapers.repec.org/RePEc:jku:nrnwps:2009_11', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9316, 26, 18, null, 'Zusätzliche Arbeitsplätze für Menschen mit Behinderung über die Quote hinaus werden mit steuerlichen Gutschriften gefördert.', '{2602}', 9301, 2, 2, null, 'Setzt an Ausstattungskosten an, die ein Viertel der Betriebe als Hürde nennt; Betriebe wünschen vor allem Zuschüsse. Studien zu Einstellungsanreizen sind gemischt (Mitnahmeeffekte); Steuergutschriften brauchen den Bundesrat und Gegenfinanzierung.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=146', 'https://pureportal.strath.ac.uk/en/publications/employer-focused-interventions-targeting-disability-employment-a-/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9317, 26, 18, null, 'Werkstätten für Menschen mit Behinderung werden abgeschafft und in Inklusionsbetriebe mit Arbeitnehmendenrechten und Mindestlohn umgewandelt.', '{2602}', 9299, 2, 1, null, 'Nach Schließung der Werkstätten fanden in Vermont viele reguläre Arbeit, in Maine sanken Stunden und Einkommen. Mindestlohn für rund 300.000 Beschäftigte und tragfähige Inklusionsbetriebe sind finanziell ungeklärt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=147', 'https://www.publicsource.org/vermont-closed-workshops-for-people-with-disabilities-what-happened-next/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9318, 26, 18, null, 'Öffentlicher Nahverkehr wird barrierefrei ausgebaut.', '{2601}', 9298, 1, 2, null, 'Investitionen beseitigen Barrieren, wo sie verbaut werden; laut Bundesrechnungshof lag die Verzögerung aber vor allem an der Steuerung, Fördergeld blieb ungenutzt. Ohne bessere Steuerung wenig Beschleunigung; der ÖPNV liegt zudem bei Ländern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=69', 'https://bundesrechnungshof.de/berichte/bmdv-verschleppt-investitionen-in-bahnhoefe', 'gemischt', '2026-10-08', false, true, 'blind');

